window.VO = [{"id":"n01","text":"You're the judge.","at":0.24,"t0":0.12,"t1":1.02},{"id":"n01j","text":"You decide if he goes to jail.","at":2.54,"t0":1.27,"t1":3.005},{"id":"n02","text":"In a city of two crore people, someone robbed a woman at a chai stall.","at":6.71,"t0":3.355,"t1":7.145},{"id":"n03","text":"Nobody saw his face, but he cut his hand on a glass, and the blood matches this man.","at":14.79,"t0":7.395,"t1":12.17},{"id":"p01","text":"Your Honour, only one person in ten thousand has this blood.","at":25.74,"t0":12.87,"t1":16.71},{"id":"p02","text":"That's a one in ten thousand chance it was someone else.","at":33.92,"t0":16.96,"t1":19.99},{"id":"n04","text":"The blood is all there is. Guilty, or not guilty?","at":40.58,"t0":20.29,"t1":23.345},{"id":"d01","text":"Judge sahab, I wasn't there.","at":47.39,"t0":23.695,"t1":25.295},{"id":"n05","text":"One in ten thousand. And he matches.","at":51.19,"t0":25.595,"t1":27.955},{"id":"n06","text":"You had two numbers. Did you put them together?","at":57.91,"t0":28.955,"t1":31.41},{"id":"n07","text":"Two crore people. One in ten thousand of them.","at":64.32,"t0":32.16,"t1":35.03},{"id":"n08","text":"That's two thousand people with his blood.","at":70.66,"t0":35.33,"t1":37.425},{"id":"n09","text":"So the blood narrows it down to two thousand. It can't tell you which one.","at":76.05,"t0":38.025,"t1":41.985},{"id":"n10","text":"It's called the prosecutor's fallacy, and it fools real judges too.","at":84.77,"t0":42.385,"t1":46.18},{"id":"n11","text":"One of those two thousand, you've met before.","at":93.26,"t0":46.63,"t1":48.99},{"id":"n12","text":"Four films. Same thief. Still free.","at":98.48,"t0":49.24,"t1":51.505},{"id":"n13","text":"Now try it on the friend who's good at maths. Don't tell them it's maths.","at":104.01,"t0":52.005,"t1":55.7},{"id":"n14","text":"So. Where was the thief sitting?","at":112.2,"t0":56.1,"t1":57.745}];
